// Analytic two-target references (NumPy 2.2.6, p x q row-major): regression
// deflation with exact dominant singular vectors of X'Y (the converged NIPALS
// limit, shared by the kernel, orthogonal-scores, SVD, power and randomized
// SVD solvers), and de Jong's (1993) SIMPLS. scikit-learn's default tol=1e-6
// NIPALS stops ~5e-6 short of the former on this design.
constexpr double kScaleExactCoefY2[kScaleP * 2] = {
    0.4973933947810975, 2.5052955832490746, -1.2807422950667673, 0.38070661558248864,
    0.3885082082101655, -0.6375563871303572, 2.6515308894065996, -0.59236011867862,
    -1.274772713729894, -0.1300636165886849, 2.4360764274911926, 0.3755312787663398};
constexpr double kScaleSimplsCoefY2[kScaleP * 2] = {
    0.5207946575018618, 2.5313352885842972, -1.279134232007274, 0.37839292312303313,
    0.35816837979798144, -0.66155341696253, 2.687190982374273, -0.5623000956881986,
    -1.2706326836444113, -0.1267563242881262, 2.4304343674427282, 0.3806905005590011};

// Agreement with the references, relative to their largest magnitude. The
// iterative two-target cases run with a tight solver tolerance so that they
// reach the exact-singular-vector limit (observed error <= 2e-14).
constexpr double kScaleReferenceTol = 1e-10;

// Units of a fitted array: fitting X 2^k, Y 2^m scales it by 2^(x k + y m).
struct Units {
    int x;
    int y;
};

struct ScaleCase {
    const char* tag;
    n4m_algorithm_t algorithm;
    n4m_solver_t solver;
    const double* y;
    std::int64_t q;
    const double* reference;   // base-scale coefficients
    double solver_tol;         // 0: default convergence tolerance
    Units weights, loadings, y_loadings, scores, y_scores;
};

// The fitted arrays checked for exact equivariance, with their units taken
// from the ScaleCase (rotations share the weights' units, coefficients are
// always 2^(m - k)).
struct ScaledFit {
    std::vector<double> arrays[7];      // coefficients, W, P, Q, R, T, U
    std::vector<double> intercept;
    std::vector<double> predictions;    // on the scaled training X
};

constexpr n4m_model_array_t kSweepArrays[7] = {
    N4M_MODEL_COEFFICIENTS, N4M_MODEL_WEIGHTS_W, N4M_MODEL_LOADINGS_P, N4M_MODEL_Y_LOADINGS_Q,
    N4M_MODEL_ROTATIONS_R, N4M_MODEL_SCORES_T, N4M_MODEL_Y_SCORES_U};
constexpr const char* kSweepArrayNames[7] = {
    "coefficients", "weights_w", "loadings_p", "y_loadings_q", "rotations_r", "scores_t",
    "y_scores_u"};

ScaledFit fit_scaled(const ScaleCase& c, int k, int m) {
    std::vector<double> xs(kScaleX, kScaleX + kScaleN * kScaleP);
    std::vector<double> ys(c.y, c.y + kScaleN * c.q);
    for (double& v : xs) v = std::ldexp(v, k);
    for (double& v : ys) v = std::ldexp(v, m);

    n4m_context_t* ctx = nullptr;
    n4m_config_t* cfg = nullptr;
    n4m_model_t* model = nullptr;
    N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_context_set_seed(ctx, kRandomizedSvdFixtureSeed) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_create(&cfg) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_n_components(cfg, kScaleA) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_algorithm(cfg, c.algorithm) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_solver(cfg, c.solver) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_center_x(cfg, 1) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_scale_x(cfg, 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_center_y(cfg, 1) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_scale_y(cfg, 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_store_scores(cfg, 1) == N4M_OK);
    if (c.solver_tol > 0.0) {
        N4M_TEST_REQUIRE(n4m_config_set_tol(cfg, c.solver_tol) == N4M_OK);
        N4M_TEST_REQUIRE(n4m_config_set_max_iter(cfg, 10000) == N4M_OK);
    }
    n4m_matrix_view_t Xv{}, Yv{};
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Xv, xs.data(), kScaleN, kScaleP,
                                                   N4M_DTYPE_F64) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Yv, ys.data(), kScaleN, c.q,
                                                   N4M_DTYPE_F64) == N4M_OK);
    const n4m_status_t st = n4m_model_fit(ctx, cfg, &Xv, &Yv, &model);
    if (st != N4M_OK) {
        throw std::runtime_error(std::string(c.tag) + ": fit refused at X 2^" + std::to_string(k) +
                                 ", Y 2^" + std::to_string(m) + " with status " +
                                 std::to_string(st));
    }
    ScaledFit out;
    n4m_array_t* arr = nullptr;
    for (std::size_t i = 0; i < 7; ++i) {
        N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, kSweepArrays[i], &arr) == N4M_OK);
        out.arrays[i] = array_values(arr);
        n4m_array_free(arr);
    }
    N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, N4M_MODEL_INTERCEPT, &arr) == N4M_OK);
    out.intercept = array_values(arr);
    n4m_array_free(arr);
    N4M_TEST_REQUIRE(n4m_model_predict_alloc(ctx, model, &Xv, &arr) == N4M_OK);
    out.predictions = array_values(arr);
    n4m_array_free(arr);
    n4m_model_destroy(model);
    n4m_config_destroy(cfg);
    n4m_context_destroy(ctx);
    return out;
}

double max_abs(const double* v, std::size_t n) {
    double out = 0.0;
    for (std::size_t i = 0; i < n; ++i) out = std::max(out, std::fabs(v[i]));
    return out;
}

void check_scale_sweep(const ScaleCase& c) {
    const auto p = static_cast<std::size_t>(kScaleP);
    const auto n = static_cast<std::size_t>(kScaleN);
    const auto nq = static_cast<std::size_t>(c.q);
    // Base-scale reference intercept (= y_mean, the scikit-learn intercept_ of
    // predict = (X - x_mean) B + intercept) and predictions.
    std::vector<double> x_mean(p, 0.0), y_mean(nq, 0.0);
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = 0; j < p; ++j) x_mean[j] += kScaleX[i * p + j] / static_cast<double>(n);
        for (std::size_t t = 0; t < nq; ++t) y_mean[t] += c.y[i * nq + t] / static_cast<double>(n);
    }
    std::vector<double> ref_pred(n * nq, 0.0);
    for (std::size_t i = 0; i < n; ++i)
        for (std::size_t t = 0; t < nq; ++t) {
            double s = y_mean[t];
            for (std::size_t j = 0; j < p; ++j) s += (kScaleX[i * p + j] - x_mean[j]) * c.reference[j * nq + t];
            ref_pred[i * nq + t] = s;
        }
    const double coef_norm = max_abs(c.reference, p * nq);
    const double y_mean_norm = max_abs(y_mean.data(), nq);
    const double pred_norm = max_abs(ref_pred.data(), n * nq);
    const Units units[7] = {{-1, 1}, c.weights, c.loadings, c.y_loadings, c.weights, c.scores,
                            c.y_scores};

    const ScaledFit base = fit_scaled(c, 0, 0);
    constexpr int kExponents[] = {0, 30, -30, 60, -60, 200, -200};
    for (int k : kExponents) {
        for (int m : kExponents) {
            const ScaledFit fit = k == 0 && m == 0 ? base : fit_scaled(c, k, m);
            const std::string where = std::string(c.tag) + " X 2^" + std::to_string(k) +
                                      ", Y 2^" + std::to_string(m);
            // Power-of-two scaling is exact, so every fitted array must be
            // exactly equivariant.
            for (std::size_t a = 0; a < 7; ++a) {
                N4M_TEST_REQUIRE(fit.arrays[a].size() == base.arrays[a].size());
                const int e = -(units[a].x * k + units[a].y * m);
                for (std::size_t i = 0; i < fit.arrays[a].size(); ++i) {
                    if (std::ldexp(fit.arrays[a][i], e) != base.arrays[a][i])
                        throw std::runtime_error(where + ": " + kSweepArrayNames[a] +
                                                 " not exactly equivariant");
                }
            }
            for (std::size_t i = 0; i < p * nq; ++i) {
                const double got = std::ldexp(fit.arrays[0][i], k - m);
                if (std::fabs(got - c.reference[i]) > kScaleReferenceTol * coef_norm)
                    throw std::runtime_error(where + ": coefficient differs from the reference");
            }
            for (std::size_t t = 0; t < nq; ++t) {
                const double got = std::ldexp(fit.intercept[t], -m);
                if (std::fabs(got - y_mean[t]) > 1e-12 * y_mean_norm)
                    throw std::runtime_error(where + ": intercept differs from the reference");
            }
            for (std::size_t i = 0; i < n * nq; ++i) {
                const double got = std::ldexp(fit.predictions[i], -m);
                if (std::fabs(got - ref_pred[i]) > kScaleReferenceTol * pred_norm)
                    throw std::runtime_error(where + ": prediction differs from the reference");
            }
        }
    }
}

// Latent-array units per solver convention (weights, loadings, Y loadings,
// X scores, Y scores), mirroring the solver code:
// unit X weights, t = X w, p = X't / t't, q = Y't / t't, u = Y q / q'q;
constexpr Units kW0{0, 0}, kP0{0, 0}, kQ{-1, 1}, kT1{1, 0}, kU1{1, 0};
// u = Y c / c'c with unit Y weights c, or u = y for one target;
constexpr Units kURaw{0, 1};
// unit-norm X scores: w = r / ||X r||, p = X't, q = Y't, u = Y q / q'q.
constexpr Units kWInv{-1, 0}, kP1{1, 0}, kQ1{0, 1}, kT0{0, 0}, kU0{0, 0};

constexpr ScaleCase kScaleCases[] = {
    {"nipals y1", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_NIPALS, kScaleY1, 1, kScalePlsCoefY1, 0.0, kW0, kP0, kQ, kT1, kU1},
    {"nipals y2", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_NIPALS, kScaleY2, 2, kScalePlsCoefY2, 0.0, kW0, kP0, kQ, kT1, kU1},
    {"pcr y1", N4M_ALGO_PCR, N4M_SOLVER_SVD, kScaleY1, 1, kScalePcrCoefY1, 0.0, kW0, kP0, kQ, kT1, kU1},
    {"pcr y2", N4M_ALGO_PCR, N4M_SOLVER_SVD, kScaleY2, 2, kScalePcrCoefY2, 0.0, kW0, kP0, kQ, kT1, kU1},
    {"simpls y1", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_SIMPLS, kScaleY1, 1, kScalePlsCoefY1, 0.0, kWInv, kP1, kQ1, kT0, kU0},
    {"simpls y2", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_SIMPLS, kScaleY2, 2, kScaleSimplsCoefY2, 0.0, kWInv, kP1, kQ1, kT0, kU0},
    {"kernel y1", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_KERNEL_ALGORITHM, kScaleY1, 1, kScalePlsCoefY1, 0.0, kWInv, kP1, kQ1, kT0, kU0},
    {"kernel y2", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_KERNEL_ALGORITHM, kScaleY2, 2, kScaleExactCoefY2, 1e-24, kWInv, kP1, kQ1, kT0, kU0},
    {"wide kernel y1", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_WIDE_KERNEL, kScaleY1, 1, kScalePlsCoefY1, 0.0, kWInv, kP1, kQ1, kT0, kU0},
    {"wide kernel y2", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_WIDE_KERNEL, kScaleY2, 2, kScaleExactCoefY2, 1e-24, kWInv, kP1, kQ1, kT0, kU0},
    {"orthogonal scores y1", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_ORTHOGONAL_SCORES, kScaleY1, 1, kScalePlsCoefY1, 0.0, kW0, kP0, kQ, kT1, kURaw},
    {"orthogonal scores y2", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_ORTHOGONAL_SCORES, kScaleY2, 2, kScaleExactCoefY2, 1e-14, kW0, kP0, kQ, kT1, kU1},
    {"svd y1", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_SVD, kScaleY1, 1, kScalePlsCoefY1, 0.0, kW0, kP0, kQ, kT1, kURaw},
    {"svd y2", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_SVD, kScaleY2, 2, kScaleExactCoefY2, 1e-24, kW0, kP0, kQ, kT1, kURaw},
    {"power y1", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_POWER, kScaleY1, 1, kScalePlsCoefY1, 0.0, kW0, kP0, kQ, kT1, kURaw},
    {"power y2", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_POWER, kScaleY2, 2, kScaleExactCoefY2, 1e-24, kW0, kP0, kQ, kT1, kURaw},
    {"randomized svd y1", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_RANDOMIZED_SVD, kScaleY1, 1, kScalePlsCoefY1, 0.0, kW0, kP0, kQ, kT1, kURaw},
    {"randomized svd y2", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_RANDOMIZED_SVD, kScaleY2, 2, kScaleExactCoefY2, 1e-24, kW0, kP0, kQ, kT1, kURaw},
};

void test_pls_scale_equivariance() {
    for (const ScaleCase& c : kScaleCases) check_scale_sweep(c);
}

// Analytic small-covariance cases. With the centred, orthogonal vectors
// a = (-1, -1, 1, 1) and b = (-1, 1, -1, 1), center on and scale off, every
// fitted array below is written down from the solver conventions, not from a
// solver run:
//  (1) X = 2^15 a, Y = 2^e b + a (e = 25, 30), one component. Y is nearly
//      orthogonal to X, so after the unit scaling the X-Y covariance is
//      ~2^-e: an absolute eps in NIPALS shrank U by ~20 % (e = 25) or refused
//      the fit (e = 30), and SIMPLS, kernel and PCR zeroed or refused U.
//      Unit X weights (NIPALS, PCR, orthogonal scores, SVD, power, randomized
//      SVD): W = P = R = 1, T = 2^15 a, Q = Y't / t't = 2^-15, coefficient
//      2^-15, U = Y Q / Q'Q = 2^15 Y (NIPALS, PCR) or U = Y (one target with
//      a unit Y weight). Unit-norm X scores (SIMPLS, kernel): T = a / 2,
//      W = R = 2^-16, P = X'T = 2^16, Q = Y'T = 2, U = Y Q / Q'Q = Y / 2.
//  (2) X = [2^30 a, b], Y = a + b, two components: singular values 2^31 and
//      2, coefficients (2^-30, 1), predictions = Y. The second PCR direction
//      (relative singular value 2^-30) was refused against an absolute eps on
//      sigma^2. PCR: W = P = R = I, T = [2^30 a, b], Q = (2^-30, 1),
//      U = [2^30 Y, Y].
//  (3) X = [a, a], Y = a + b, two components: the second component does not
//      exist (X has rank 1). Every solver publishes it as a null component
//      flagged unresolved (zero W, P, Q, R, T, U columns): coefficients
//      (1/2, 1/2) of the one-component model, predictions = a.
// Every fit also publishes its component resolution, (n + a) eps ||X||_F
// ||Y||_F for the PLS solvers and (n + p) eps sigma_max ||Y||_F for PCR, and
// per-component unresolved flags; every fit is exported and re-imported and
// the restored arrays (resolution and flags included) must be bit-identical.
constexpr double kVecA[4] = {-1.0, -1.0, 1.0, 1.0};
constexpr double kVecB[4] = {-1.0, 1.0, -1.0, 1.0};
constexpr double kAnalyticTol = 1e-12;

struct AnalyticSolver {
    const char* tag;
    n4m_algorithm_t algorithm;
    n4m_solver_t solver;
    bool unit_scores;    // unit-norm X scores (SIMPLS, kernel)
    bool raw_y_scores;   // U = y for one target (unit Y weight)
};

constexpr AnalyticSolver kAnalyticSolvers[] = {
    {"nipals", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_NIPALS, false, false},
    {"pcr", N4M_ALGO_PCR, N4M_SOLVER_SVD, false, false},
    {"simpls", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_SIMPLS, true, false},
    {"kernel", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_KERNEL_ALGORITHM, true, false},
    {"wide kernel", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_WIDE_KERNEL, true, false},
    {"orthogonal scores", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_ORTHOGONAL_SCORES, false, true},
    {"svd", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_SVD, false, true},
    {"power", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_POWER, false, true},
    {"randomized svd", N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_RANDOMIZED_SVD, false, true},
};

// Fitted arrays in kSweepArrays order (coefficients, W, P, Q, R, T, U) plus
// predictions on the training X; an empty expected array is not checked.
struct AnalyticArrays {
    std::vector<double> arrays[7];
    std::vector<double> predictions;
    std::vector<double> resolution;  // N4M_MODEL_COMPONENT_RESOLUTION
    std::vector<double> unresolved;  // N4M_MODEL_UNRESOLVED_COMPONENTS
};

AnalyticArrays model_arrays(n4m_context_t* ctx, const n4m_model_t* model,
                            const n4m_matrix_view_t& Xv) {
    AnalyticArrays out;
    n4m_array_t* arr = nullptr;
    for (std::size_t i = 0; i < 7; ++i) {
        N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, kSweepArrays[i], &arr) == N4M_OK);
        out.arrays[i] = array_values(arr);
        n4m_array_free(arr);
    }
    N4M_TEST_REQUIRE(n4m_model_predict_alloc(ctx, model, &Xv, &arr) == N4M_OK);
    out.predictions = array_values(arr);
    n4m_array_free(arr);
    N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, N4M_MODEL_COMPONENT_RESOLUTION, &arr) ==
                     N4M_OK);
    out.resolution = array_values(arr);
    n4m_array_free(arr);
    N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, N4M_MODEL_UNRESOLVED_COMPONENTS, &arr) ==
                     N4M_OK);
    out.unresolved = array_values(arr);
    n4m_array_free(arr);
    return out;
}

// Fits with center on, scale off and stored scores; returns the fit status
// and, on success, the fitted arrays (`fitted`) and those of the exported and
// re-imported model (`restored`).
n4m_status_t fit_analytic(const AnalyticSolver& s, std::vector<double> x, std::int64_t p,
                          std::vector<double> y, std::int32_t components,
                          AnalyticArrays& fitted, AnalyticArrays& restored,
                          std::int64_t q = 1, double tol = 0.0) {
    n4m_context_t* ctx = nullptr;
    n4m_config_t* cfg = nullptr;
    N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_context_set_seed(ctx, kRandomizedSvdFixtureSeed) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_create(&cfg) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_n_components(cfg, components) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_algorithm(cfg, s.algorithm) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_solver(cfg, s.solver) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_center_x(cfg, 1) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_scale_x(cfg, 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_center_y(cfg, 1) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_scale_y(cfg, 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_store_scores(cfg, 1) == N4M_OK);
    if (tol > 0.0) N4M_TEST_REQUIRE(n4m_config_set_tol(cfg, tol) == N4M_OK);
    n4m_matrix_view_t Xv{}, Yv{};
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Xv, x.data(), 4, p, N4M_DTYPE_F64) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Yv, y.data(), 4, q, N4M_DTYPE_F64) == N4M_OK);
    n4m_model_t* model = nullptr;
    const n4m_status_t st = n4m_model_fit(ctx, cfg, &Xv, &Yv, &model);
    if (st == N4M_OK) {
        fitted = model_arrays(ctx, model, Xv);
        std::size_t bytes = 0;
        N4M_TEST_REQUIRE(n4m_model_export_size(model, &bytes) == N4M_OK);
        std::vector<unsigned char> payload(bytes);
        std::size_t written = 0;
        N4M_TEST_REQUIRE(n4m_model_export_to_buffer(model, payload.data(), payload.size(),
                                                     &written) == N4M_OK);
        n4m_model_t* imported = nullptr;
        N4M_TEST_REQUIRE(n4m_model_import_from_buffer(ctx, payload.data(), written,
                                                      &imported) == N4M_OK);
        restored = model_arrays(ctx, imported, Xv);
        n4m_model_destroy(imported);
        n4m_model_destroy(model);
    }
    n4m_config_destroy(cfg);
    n4m_context_destroy(ctx);
    return st;
}

// Elementwise relative agreement; a zero expected entry is compared against
// the largest expected magnitude of the array.
void expect_analytic(const std::string& where, const char* name, const std::vector<double>& got,
                     const std::vector<double>& want) {
    if (want.empty()) return;
    if (got.size() != want.size())
        throw std::runtime_error(where + ": " + name + " has the wrong size");
    const double largest = max_abs(want.data(), want.size());
    for (std::size_t i = 0; i < want.size(); ++i) {
        const double scale = want[i] != 0.0 ? std::fabs(want[i]) : largest;
        if (!(std::fabs(got[i] - want[i]) <= kAnalyticTol * scale))
            throw std::runtime_error(where + ": " + name + "[" + std::to_string(i) +
                                     "] = " + std::to_string(got[i]) + ", expected " +
                                     std::to_string(want[i]));
    }
}

void expect_fit(const std::string& where, const AnalyticArrays& fitted,
                const AnalyticArrays& restored, const AnalyticArrays& want) {
    for (std::size_t i = 0; i < 7; ++i) {
        expect_analytic(where, kSweepArrayNames[i], fitted.arrays[i], want.arrays[i]);
        if (restored.arrays[i] != fitted.arrays[i])
            throw std::runtime_error(where + ": " + kSweepArrayNames[i] +
                                     " changed through export/import");
    }
    expect_analytic(where, "predictions", fitted.predictions, want.predictions);
    if (restored.predictions != fitted.predictions)
        throw std::runtime_error(where + ": predictions changed through export/import");
    expect_analytic(where, "resolution", fitted.resolution, want.resolution);
    if (!want.unresolved.empty() && fitted.unresolved != want.unresolved)
        throw std::runtime_error(where + ": unresolved flags differ from the expected ones");
    if (restored.resolution != fitted.resolution || restored.unresolved != fitted.unresolved)
        throw std::runtime_error(where + ": resolution or flags changed through export/import");
}

// Frobenius norm of a centred array, in long double (independent of the
// solver's accumulation order).
long double frobenius(const std::vector<double>& v) {
    long double ss = 0.0L;
    for (double x : v) ss += static_cast<long double>(x) * static_cast<long double>(x);
    return std::sqrt(ss);
}

// Expected component resolution, n = 4: PLS (n + a) eps ||X||_F ||Y||_F,
// PCR (n + p) eps sigma_max ||Y||_F.
std::vector<double> expected_resolution(const AnalyticSolver& s, const std::vector<double>& x,
                                        int p, const std::vector<double>& y, int components,
                                        long double sigma_max) {
    const long double eps = static_cast<long double>(std::numeric_limits<double>::epsilon());
    const long double value = s.algorithm == N4M_ALGO_PCR
                                  ? (4 + p) * eps * sigma_max * frobenius(y)
                                  : (4 + components) * eps * frobenius(x) * frobenius(y);
    return {static_cast<double>(value)};
}

std::vector<double> combine(double ca, double cb) {
    std::vector<double> out(4);
    for (std::size_t i = 0; i < 4; ++i) out[i] = ca * kVecA[i] + cb * kVecB[i];
    return out;
}

// Every latent column `comp` (W, P, R: p x a; Q: q x a; T, U: 4 x a) of a
// fitted model is exactly zero (a null component).
void expect_null_component(const std::string& where, const AnalyticArrays& fitted,
                           std::size_t a, std::size_t comp, std::size_t p, std::size_t q = 1) {
    const std::size_t rows[7] = {0, p, p, q, p, 4, 4};
    for (std::size_t i = 1; i < 7; ++i) {
        const std::vector<double>& values = fitted.arrays[i];
        if (values.size() != rows[i] * a)
            throw std::runtime_error(where + ": " + kSweepArrayNames[i] + " has the wrong size");
        for (std::size_t row = 0; row < rows[i]; ++row) {
            const double value = values[row * a + comp];
            if (value != 0.0 || std::signbit(value))
                throw std::runtime_error(where + ": " + kSweepArrayNames[i] + " column " +
                                         std::to_string(comp) + " of the null component is " +
                                         std::to_string(value));
        }
    }
}

void test_pls_small_covariance_analytic() {
    // (1) one feature, Y nearly orthogonal to X.
    for (const int e : {25, 30}) {
        const std::vector<double> x = combine(std::ldexp(1.0, 15), 0.0);
        const std::vector<double> y = combine(1.0, std::ldexp(1.0, e));
        for (const AnalyticSolver& s : kAnalyticSolvers) {
            const std::string where = std::string(s.tag) + " X = 2^15 a, Y = 2^" +
                                      std::to_string(e) + " b + a";
            AnalyticArrays fitted, restored, want;
            const n4m_status_t st = fit_analytic(s, x, 1, y, 1, fitted, restored);
            if (st != N4M_OK)
                throw std::runtime_error(where + ": fit refused with status " +
                                         std::to_string(st));
            want.arrays[0] = {std::ldexp(1.0, -15)};
            if (s.unit_scores) {
                want.arrays[1] = {std::ldexp(1.0, -16)};
                want.arrays[2] = {std::ldexp(1.0, 16)};
                want.arrays[3] = {2.0};
                want.arrays[4] = {std::ldexp(1.0, -16)};
                want.arrays[5] = combine(0.5, 0.0);
                want.arrays[6] = combine(0.5, std::ldexp(1.0, e - 1));
            } else {
                want.arrays[1] = {1.0};
                want.arrays[2] = {1.0};
                want.arrays[3] = {std::ldexp(1.0, -15)};
                want.arrays[4] = {1.0};
                want.arrays[5] = x;
                want.arrays[6] = s.raw_y_scores
                                     ? y
                                     : combine(std::ldexp(1.0, 15), std::ldexp(1.0, e + 15));
            }
            want.predictions = combine(1.0, 0.0);
            want.resolution = expected_resolution(s, x, 1, y, 1, std::ldexp(1.0L, 16));
            want.unresolved = {0.0};
            expect_fit(where, fitted, restored, want);
        }
    }

    // (2) two features with singular values 2^31 and 2.
    {
        std::vector<double> x(8);
        for (std::size_t i = 0; i < 4; ++i) {
            x[i * 2] = std::ldexp(kVecA[i], 30);
            x[i * 2 + 1] = kVecB[i];
        }
        const std::vector<double> y = combine(1.0, 1.0);
        for (const AnalyticSolver& s : kAnalyticSolvers) {
            const std::string where = std::string(s.tag) + " X = [2^30 a, b], Y = a + b";
            AnalyticArrays fitted, restored, want;
            const n4m_status_t st = fit_analytic(s, x, 2, y, 2, fitted, restored);
            if (st != N4M_OK)
                throw std::runtime_error(where + ": fit refused with status " +
                                         std::to_string(st));
            want.arrays[0] = {std::ldexp(1.0, -30), 1.0};
            if (s.algorithm == N4M_ALGO_PCR) {
                const std::vector<double> identity = {1.0, 0.0, 0.0, 1.0};
                want.arrays[1] = identity;
                want.arrays[2] = identity;
                want.arrays[3] = {std::ldexp(1.0, -30), 1.0};
                want.arrays[4] = identity;
                want.arrays[5] = x;
                std::vector<double> u(8);
                for (std::size_t i = 0; i < 4; ++i) {
                    u[i * 2] = std::ldexp(y[i], 30);
                    u[i * 2 + 1] = y[i];
                }
                want.arrays[6] = u;
            }
            want.predictions = y;
            want.resolution = expected_resolution(s, x, 2, y, 2, std::ldexp(1.0L, 31));
            want.unresolved = {0.0, 0.0};
            expect_fit(where, fitted, restored, want);
        }
    }

    // (4) X = [a, 2^-32 b], Y = b (spread 2^32), one component. PLS follows
    // the tiny column: coefficients (0, 2^32), predictions = Y; unit X
    // weights: W = P = R = (0, 1), T = 2^-32 b, Q = 2^32, U = 2^-32 b (or Y);
    // unit-norm X scores: T = b / 2, W = R = (0, 2^31), P = (0, 2^-31), Q = 2,
    // U = Y / 2. PCR keeps the dominant direction a, which Y does not
    // correlate with: Q = 0 and coefficients 0. Its Y score u = Y q / q'q is
    // mathematically undefined (q = 0): the component is flagged unresolved
    // and its U column is zero.
    {
        std::vector<double> x(8);
        for (std::size_t i = 0; i < 4; ++i) {
            x[i * 2] = kVecA[i];
            x[i * 2 + 1] = std::ldexp(kVecB[i], -32);
        }
        const std::vector<double> y = combine(0.0, 1.0);
        for (const AnalyticSolver& s : kAnalyticSolvers) {
            const std::string where = std::string(s.tag) + " X = [a, 2^-32 b], Y = b";
            AnalyticArrays fitted, restored, want;
            const n4m_status_t st = fit_analytic(s, x, 2, y, 1, fitted, restored);
            if (st != N4M_OK)
                throw std::runtime_error(where + ": fit refused with status " +
                                         std::to_string(st));
            if (s.algorithm == N4M_ALGO_PCR) {
                want.arrays[0] = {0.0, 0.0};
                want.arrays[1] = {1.0, 0.0};
                want.arrays[2] = {1.0, 0.0};
                want.arrays[3] = {0.0};
                want.arrays[4] = {1.0, 0.0};
                want.arrays[5] = combine(1.0, 0.0);
                want.arrays[6] = {0.0, 0.0, 0.0, 0.0};
                want.predictions = {0.0, 0.0, 0.0, 0.0};
                want.unresolved = {1.0};
            } else {
                want.arrays[0] = {0.0, std::ldexp(1.0, 32)};
                if (s.unit_scores) {
                    want.arrays[1] = {0.0, std::ldexp(1.0, 31)};
                    want.arrays[2] = {0.0, std::ldexp(1.0, -31)};
                    want.arrays[3] = {2.0};
                    want.arrays[4] = {0.0, std::ldexp(1.0, 31)};
                    want.arrays[5] = combine(0.0, 0.5);
                    want.arrays[6] = combine(0.0, 0.5);
                } else {
                    want.arrays[1] = {0.0, 1.0};
                    want.arrays[2] = {0.0, 1.0};
                    want.arrays[3] = {std::ldexp(1.0, 32)};
                    want.arrays[4] = {0.0, 1.0};
                    want.arrays[5] = combine(0.0, std::ldexp(1.0, -32));
                    want.arrays[6] = s.raw_y_scores ? y : combine(0.0, std::ldexp(1.0, -32));
                }
                want.predictions = y;
                want.unresolved = {0.0};
            }
            want.resolution = expected_resolution(s, x, 2, y, 1, 2.0L);
            expect_fit(where, fitted, restored, want);
        }
    }

    // (3) rank-one X: the second component is a flagged null component.
    {
        std::vector<double> x(8);
        for (std::size_t i = 0; i < 4; ++i) x[i * 2] = x[i * 2 + 1] = kVecA[i];
        const std::vector<double> y = combine(1.0, 1.0);
        for (const AnalyticSolver& s : kAnalyticSolvers) {
            const std::string where = std::string(s.tag) + " X = [a, a], Y = a + b";
            AnalyticArrays fitted, restored, want;
            const n4m_status_t st = fit_analytic(s, x, 2, y, 2, fitted, restored);
            if (st != N4M_OK)
                throw std::runtime_error(where + ": fit refused with status " +
                                         std::to_string(st));
            want.arrays[0] = {0.5, 0.5};
            want.predictions = combine(1.0, 0.0);
            want.resolution = expected_resolution(s, x, 2, y, 2, std::sqrt(8.0L));
            want.unresolved = {0.0, 1.0};
            expect_fit(where, fitted, restored, want);
            expect_null_component(where, fitted, 2, 1, 2);
        }
    }
}

// Unresolved components and multi-target resolution, with the centred,
// orthogonal a = (-3, -1, 1, 3), b = (1, -3, 3, -1) (a'a = b'b = 20):
//  (5) X = a, Y = b + 2^-50 a, one component. Exactly, Q = 2^-50 and
//      U = Y q / q'q = 2^50 Y, but ||Y't|| = 20 2^-50 ~ 1.8e-14 does not
//      exceed the PCR resolution 5 eps sqrt(20) ||Y|| ~ 2.2e-14: PCR keeps
//      the component (W = P = R = 1, T = a, Q = 2^-50, coefficient 2^-50),
//      flags it unresolved and leaves its U column zero. The PLS
//      cross-covariance is unresolved as well: every PLS solver (and PLS-DA)
//      publishes a null component flagged unresolved (W = P = Q = R = 0,
//      T = U = 0), coefficient 0, predictions = the Y mean (0).
//  (6) X = [2 a, b], Y = [a + 2^-48 b, 3 a - 2^-48 b] (exactly
//      representable, as are all its products and partial sums), two PCR
//      components: W = P = R = I, T = X, Q = [[1/2, 2^-48], [3/2, -2^-48]],
//      coefficients Q', predictions = Y; the second component
//      (||Y't_2|| = 20 sqrt(2) 2^-48 ~ 1.0e-13) is below the resolution
//      6 eps sqrt(80) ||Y|| ~ 1.7e-13 and unresolved, U = [Y q_1 / q_1'q_1, 0].
//  (7) X = [a, b], Y = [a, c, ..., c] with 64 copies of c = 2^-29 a + 2^-51 b,
//      two components. After the first component each residual c column is
//      2^-51 b, below scikit-learn's 10 eps mask, yet together they carry
//      ||X_1'Y_1||_F = 64 * 20 * 2^-51 ~ 1.8e-14 above the resolution
//      6 eps ||X|| ||Y|| ~ 9.4e-15. Every solver resolves both components:
//      coefficients [[1, 2^-29 ...], [0, 2^-51 ...]], predictions = Y.
//      NIPALS: W = P = I, T = X, Q = [[1, 0], [2^-29, 2^-51] x 64],
//      U = [Y q_1 / q_1'q_1, Y_1 q_2 / q_2'q_2 = b] with
//      Y q_1 / q_1'q_1 = a + 64 2^-80 / (1 + 2^-52) b.
//  (8) As (7) with the unit vectors a = (-1, -1, 1, 1), b = (-1, 1, -1, 1)
//      and 100 copies of c = 2^-29 a + 2^-52 b: the residual c columns are
//      2^-52 b, no entry above eps (NIPALS and kernel took that for a constant
//      residual and refused), while ||X_1'Y_1||_F = 10 * 4 * 2^-52 ~ 8.9e-15
//      exceeds the resolution 6 eps ||X|| ||Y|| ~ 7.5e-15. Coefficients
//      [[1, 2^-29 ...], [0, 2^-52 ...]], predictions = Y, for every solver.
constexpr double kVecA3[4] = {-3.0, -1.0, 1.0, 3.0};
constexpr double kVecB3[4] = {1.0, -3.0, 3.0, -1.0};

std::vector<double> combine3(double ca, double cb) {
    std::vector<double> out(4);
    for (std::size_t i = 0; i < 4; ++i) out[i] = ca * kVecA3[i] + cb * kVecB3[i];
    return out;
}

void test_pls_unresolved_components() {
    const long double sqrt20 = std::sqrt(20.0L);
    // (5)
    {
        const std::vector<double> x = combine3(1.0, 0.0);
        const std::vector<double> y = combine3(std::ldexp(1.0, -50), 1.0);
        for (const AnalyticSolver& s : kAnalyticSolvers) {
            const std::string where = std::string(s.tag) + " X = a, Y = b + 2^-50 a";
            AnalyticArrays fitted, restored, want;
            const n4m_status_t st = fit_analytic(s, x, 1, y, 1, fitted, restored);
            if (st != N4M_OK)
                throw std::runtime_error(where + ": fit refused with status " + std::to_string(st));
            want.resolution = expected_resolution(s, x, 1, y, 1, sqrt20);
            want.unresolved = {1.0};
            if (s.algorithm != N4M_ALGO_PCR) {
                const std::vector<double> zeros = {0.0, 0.0, 0.0, 0.0};
                want.arrays[0] = {0.0};
                for (std::size_t i = 1; i < 5; ++i) want.arrays[i] = {0.0};
                want.arrays[5] = zeros;
                want.arrays[6] = zeros;
                want.predictions = zeros;
                expect_fit(where, fitted, restored, want);
                expect_null_component(where, fitted, 1, 0, 1);
                // PLS-DA runs the same solvers.
                AnalyticSolver da = s;
                da.algorithm = N4M_ALGO_PLS_DA;
                AnalyticArrays da_fitted, da_restored;
                if (fit_analytic(da, x, 1, y, 1, da_fitted, da_restored) != N4M_OK)
                    throw std::runtime_error(where + ": PLS-DA fit refused");
                expect_fit(where + " (PLS-DA)", da_fitted, da_restored, want);
                continue;
            }
            want.arrays[0] = {std::ldexp(1.0, -50)};
            want.arrays[1] = {1.0};
            want.arrays[2] = {1.0};
            want.arrays[3] = {std::ldexp(1.0, -50)};
            want.arrays[4] = {1.0};
            want.arrays[5] = x;
            want.arrays[6] = {0.0, 0.0, 0.0, 0.0};
            want.predictions = combine3(std::ldexp(1.0, -50), 0.0);
            expect_fit(where, fitted, restored, want);
        }
    }
    // (6)
    {
        std::vector<double> x(8), y(8);
        for (std::size_t i = 0; i < 4; ++i) {
            x[i * 2] = 2.0 * kVecA3[i];
            x[i * 2 + 1] = kVecB3[i];
            y[i * 2] = kVecA3[i] + std::ldexp(kVecB3[i], -48);
            y[i * 2 + 1] = 3.0 * kVecA3[i] - std::ldexp(kVecB3[i], -48);
        }
        const AnalyticSolver& pcr = kAnalyticSolvers[1];
        const std::string where = "pcr X = [2a, b], Y = [a + 2^-48 b, 3a - 2^-48 b]";
        AnalyticArrays fitted, restored, want;
        const n4m_status_t st = fit_analytic(pcr, x, 2, y, 2, fitted, restored, 2);
        if (st != N4M_OK)
            throw std::runtime_error(where + ": fit refused with status " + std::to_string(st));
        const double tiny = std::ldexp(1.0, -48);
        const std::vector<double> identity = {1.0, 0.0, 0.0, 1.0};
        want.arrays[0] = {0.5, 1.5, tiny, -tiny};
        want.arrays[1] = identity;
        want.arrays[2] = identity;
        want.arrays[3] = {0.5, tiny, 1.5, -tiny};
        want.arrays[4] = identity;
        want.arrays[5] = x;
        std::vector<double> u(8, 0.0);
        for (std::size_t i = 0; i < 4; ++i)
            u[i * 2] = (0.5 * y[i * 2] + 1.5 * y[i * 2 + 1]) / 2.5;
        want.arrays[6] = u;
        want.predictions = y;
        want.resolution = expected_resolution(pcr, x, 2, y, 2, 2.0L * sqrt20);
        want.unresolved = {0.0, 1.0};
        expect_fit(where, fitted, restored, want);
    }
    // (7)
    {
        constexpr std::size_t q = 65;
        std::vector<double> x(8), y(4 * q);
        for (std::size_t i = 0; i < 4; ++i) {
            x[i * 2] = kVecA3[i];
            x[i * 2 + 1] = kVecB3[i];
            y[i * q] = kVecA3[i];
            for (std::size_t t = 1; t < q; ++t)
                y[i * q + t] = std::ldexp(kVecA3[i], -29) + std::ldexp(kVecB3[i], -51);
        }
        std::vector<double> coefficients(2 * q), y_loadings(q * 2), u(8);
        coefficients[0] = 1.0;
        coefficients[q] = 0.0;
        y_loadings[0] = 1.0;
        y_loadings[1] = 0.0;
        for (std::size_t t = 1; t < q; ++t) {
            coefficients[t] = std::ldexp(1.0, -29);
            coefficients[q + t] = std::ldexp(1.0, -51);
            y_loadings[t * 2] = std::ldexp(1.0, -29);
            y_loadings[t * 2 + 1] = std::ldexp(1.0, -51);
        }
        const double tilt = std::ldexp(64.0, -80) / (1.0 + std::ldexp(1.0, -52));
        for (std::size_t i = 0; i < 4; ++i) {
            u[i * 2] = kVecA3[i] + tilt * kVecB3[i];
            u[i * 2 + 1] = kVecB3[i];
        }
        for (const AnalyticSolver& s : kAnalyticSolvers) {
            const std::string where = std::string(s.tag) + " X = [a, b], Y = [a, 64 x (2^-29 a + 2^-51 b)]";
            AnalyticArrays fitted, restored, want;
            const n4m_status_t st = fit_analytic(s, x, 2, y, 2, fitted, restored, static_cast<std::int64_t>(q));
            if (st != N4M_OK)
                throw std::runtime_error(where + ": fit refused with status " + std::to_string(st));
            if (s.solver == N4M_SOLVER_NIPALS) {
                // NIPALS reproduces every entry; the other solvers resolve
                // the 2^-51 coefficients to ~1e-10 of themselves, i.e. to
                // rounding of their column (checked below).
                want.arrays[0] = coefficients;
                const std::vector<double> identity = {1.0, 0.0, 0.0, 1.0};
                want.arrays[1] = identity;
                want.arrays[2] = identity;
                want.arrays[3] = y_loadings;
                want.arrays[4] = identity;
                want.arrays[5] = x;
                want.arrays[6] = u;
            }
            want.predictions = y;
            want.resolution = expected_resolution(s, x, 2, y, 2, sqrt20);
            want.unresolved = {0.0, 0.0};
            expect_fit(where, fitted, restored, want);
            const std::vector<double>& got = fitted.arrays[0];
            for (std::size_t t = 0; t < q; ++t) {
                const double column = std::max(std::fabs(coefficients[t]),
                                               std::fabs(coefficients[q + t]));
                for (std::size_t f = 0; f < 2; ++f) {
                    const std::size_t k = static_cast<std::size_t>(f * q + t);
                    if (!(std::fabs(got[k] - coefficients[k]) <= kAnalyticTol * column))
                        throw std::runtime_error(where + ": coefficient (" + std::to_string(f) +
                                                 ", " + std::to_string(t) + ") is wrong");
                }
            }
        }
    }
    // (8)
    {
        constexpr std::size_t q = 101;
        std::vector<double> x(8), y(4 * q), coefficients(2 * q, 0.0);
        for (std::size_t i = 0; i < 4; ++i) {
            x[i * 2] = kVecA[i];
            x[i * 2 + 1] = kVecB[i];
            y[i * q] = kVecA[i];
            for (std::size_t t = 1; t < q; ++t)
                y[i * q + t] = std::ldexp(kVecA[i], -29) + std::ldexp(kVecB[i], -52);
        }
        coefficients[0] = 1.0;
        for (std::size_t t = 1; t < q; ++t) {
            coefficients[t] = std::ldexp(1.0, -29);
            coefficients[q + t] = std::ldexp(1.0, -52);
        }
        for (const AnalyticSolver& s : kAnalyticSolvers) {
            const std::string where = std::string(s.tag) +
                                      " X = [a, b], Y = [a, 100 x (2^-29 a + 2^-52 b)]";
            AnalyticArrays fitted, restored, want;
            const n4m_status_t st = fit_analytic(s, x, 2, y, 2, fitted, restored, static_cast<std::int64_t>(q));
            if (st != N4M_OK)
                throw std::runtime_error(where + ": fit refused with status " + std::to_string(st));
            want.arrays[0] = coefficients;
            want.predictions = y;
            want.resolution = expected_resolution(s, x, 2, y, 2, 2.0L);
            want.unresolved = {0.0, 0.0};
            expect_fit(where, fitted, restored, want);
        }
    }
}

// (9) Close leading singular values: X = [a3, b3], Y = [a3 + d b3, d a3 + b3]
// with d = 2^-e (e = 12, 20, 30), one component. X'Y = 20 [[1, d], [d, 1]]
// has the singular values 20 (1 +- d) and the dominant singular vectors
// (1, 1) / sqrt 2 on both sides. The power-type iterations contract their
// error by (1 - d)^2 / (1 + d)^2 per step: SIMPLS (and every iterative solver
// at tol 1e-12) failed to converge, and NIPALS, kernel, power and randomized
// SVD stopped at the default tol 1e-6 with weights (1, 0) (coefficients off by
// 1/2). Both the default tol and tol = 1e-12 are checked. With s = 1 / sqrt 2 and h = (1 + d) / 2: coefficients h everywhere,
// predictions h (a3 + b3) in both columns. Unit X weights (NIPALS, orthogonal
// scores, SVD, power, randomized SVD): W = P = R = (s, s), T = s (a3 + b3),
// Q = (1 + d) s (1, 1), U = s (a3 + b3) (u = Y q / q'q) or (1 + d) s (a3 + b3)
// (u = Y c, unit Y weights). Unit-norm X scores (SIMPLS, kernel):
// W = R = (1, 1) / sqrt 40, T = (a3 + b3) / sqrt 40, P = sqrt 10 (1, 1),
// Q = (1 + d) sqrt 10 (1, 1), U = (a3 + b3) / sqrt 40. PLS-DA runs the same solvers;
// canonical PLS (NIPALS and SVD) has the weights (s, s) as well.
void test_pls_close_singular_values() {
    const double s = 1.0 / std::sqrt(2.0);
    const double r40 = 1.0 / std::sqrt(40.0);
    const double r10 = std::sqrt(10.0);
    const std::vector<double> ab = combine3(1.0, 1.0);
    for (const int e : {12, 20, 30}) {
        const double d = std::ldexp(1.0, -e);
        const double h = (1.0 + d) / 2.0;
        std::vector<double> x(8), y(8), predictions(8), t(4), u(4);
        for (std::size_t i = 0; i < 4; ++i) {
            x[i * 2] = kVecA3[i];
            x[i * 2 + 1] = kVecB3[i];
            y[i * 2] = kVecA3[i] + d * kVecB3[i];
            y[i * 2 + 1] = d * kVecA3[i] + kVecB3[i];
            predictions[i * 2] = predictions[i * 2 + 1] = h * ab[i];
        }
        for (const AnalyticSolver& solver : kAnalyticSolvers) {
            if (solver.algorithm == N4M_ALGO_PCR) continue;  // X'X = 20 I: PCR is undetermined
            for (const n4m_algorithm_t algorithm : {N4M_ALGO_PLS_REGRESSION, N4M_ALGO_PLS_DA})
            for (const double tol : {0.0, 1e-12}) {
                AnalyticSolver run = solver;
                run.algorithm = algorithm;
                const std::string where = std::string(solver.tag) +
                                          (algorithm == N4M_ALGO_PLS_DA ? " (PLS-DA)" : "") +
                                          (tol > 0.0 ? " tol 1e-12" : "") +
                                          " X = [a3, b3], Y = [a3 + 2^-" + std::to_string(e) +
                                          " b3, 2^-" + std::to_string(e) + " a3 + b3]";
                AnalyticArrays fitted, restored, want;
                const n4m_status_t st = fit_analytic(run, x, 2, y, 1, fitted, restored, 2, tol);
                if (st != N4M_OK)
                    throw std::runtime_error(where + ": fit refused with status " +
                                             std::to_string(st));
                want.arrays[0] = {h, h, h, h};
                if (solver.unit_scores) {
                    want.arrays[1] = {r40, r40};
                    want.arrays[2] = {r10, r10};
                    want.arrays[3] = {(1.0 + d) * r10, (1.0 + d) * r10};
                    want.arrays[4] = {r40, r40};
                    for (std::size_t i = 0; i < 4; ++i) {
                        t[i] = r40 * ab[i];
                        u[i] = r40 * ab[i];
                    }
                } else {
                    want.arrays[1] = {s, s};
                    want.arrays[2] = {s, s};
                    want.arrays[3] = {(1.0 + d) * s, (1.0 + d) * s};
                    want.arrays[4] = {s, s};
                    for (std::size_t i = 0; i < 4; ++i) {
                        t[i] = s * ab[i];
                        u[i] = (solver.raw_y_scores && solver.solver != N4M_SOLVER_ORTHOGONAL_SCORES
                                    ? (1.0 + d) * s
                                    : s) *
                               ab[i];
                    }
                }
                want.arrays[5] = t;
                want.arrays[6] = u;
                want.predictions = predictions;
                want.resolution = expected_resolution(
                    run, x, 2, y, 1, 20.0L * (1.0L + static_cast<long double>(d)));
                want.unresolved = {0.0};
                expect_fit(where, fitted, restored, want);
            }
        }
        for (const n4m_solver_t solver : {N4M_SOLVER_NIPALS, N4M_SOLVER_SVD}) {
            const std::string where = std::string("canonical ") +
                                      (solver == N4M_SOLVER_SVD ? "svd" : "nipals") +
                                      " d = 2^-" + std::to_string(e);
            n4m_context_t* ctx = nullptr;
            n4m_config_t* cfg = nullptr;
            N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_create(&cfg) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_n_components(cfg, 1) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_algorithm(cfg, N4M_ALGO_PLS_CANONICAL) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_solver(cfg, solver) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_deflation(cfg, N4M_DEFLATION_CANONICAL) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_scale_x(cfg, 0) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_scale_y(cfg, 0) == N4M_OK);
            n4m_matrix_view_t Xv{}, Yv{};
            N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Xv, x.data(), 4, 2, N4M_DTYPE_F64) ==
                             N4M_OK);
            N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Yv, y.data(), 4, 2, N4M_DTYPE_F64) ==
                             N4M_OK);
            n4m_model_t* model = nullptr;
            const n4m_status_t st = n4m_model_fit(ctx, cfg, &Xv, &Yv, &model);
            if (st != N4M_OK)
                throw std::runtime_error(where + ": fit refused with status " + std::to_string(st));
            n4m_array_t* arr = nullptr;
            N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, N4M_MODEL_WEIGHTS_W, &arr) == N4M_OK);
            expect_analytic(where, "weights_w", array_values(arr), {s, s});
            n4m_array_free(arr);
            n4m_model_destroy(model);
            n4m_config_destroy(cfg);
            n4m_context_destroy(ctx);
        }
    }
}

// (11) PCR with exactly equal singular values: X = [a3, b3] (X'X = 20 I),
// Y = [a3 + d b3, d a3 + b3], d = 2^-12. Only the singular subspace is
// defined; PCR returns the deterministic Jacobi basis in column order, so
// with one component W = (1, 0), T = a3, coefficients [[1, d], [0, 0]], and
// with the columns swapped (X = [b3, a3]) again W = (1, 0) (now along b3),
// coefficients [[d, 1], [0, 0]]. Keeping both components does not depend on
// the convention: W = I, coefficients [[1, d], [d, 1]].
void test_pcr_equal_singular_values() {
    const double d = std::ldexp(1.0, -12);
    for (const bool swapped : {false, true}) {
        std::vector<double> x(8), y(8);
        for (std::size_t i = 0; i < 4; ++i) {
            x[i * 2] = swapped ? kVecB3[i] : kVecA3[i];
            x[i * 2 + 1] = swapped ? kVecA3[i] : kVecB3[i];
            y[i * 2] = kVecA3[i] + d * kVecB3[i];
            y[i * 2 + 1] = d * kVecA3[i] + kVecB3[i];
        }
        for (const std::int32_t components : {1, 2}) {
            const std::string where = std::string("pcr equal singular values") +
                                      (swapped ? " X = [b3, a3]" : " X = [a3, b3]") + ", " +
                                      std::to_string(components) + " component(s)";
            n4m_context_t* ctx = nullptr;
            n4m_config_t* cfg = nullptr;
            N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_create(&cfg) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_n_components(cfg, components) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_algorithm(cfg, N4M_ALGO_PCR) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_solver(cfg, N4M_SOLVER_SVD) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_scale_x(cfg, 0) == N4M_OK);
            N4M_TEST_REQUIRE(n4m_config_set_scale_y(cfg, 0) == N4M_OK);
            n4m_matrix_view_t Xv{}, Yv{};
            N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Xv, x.data(), 4, 2, N4M_DTYPE_F64) ==
                             N4M_OK);
            N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Yv, y.data(), 4, 2, N4M_DTYPE_F64) ==
                             N4M_OK);
            n4m_model_t* model = nullptr;
            N4M_TEST_REQUIRE(n4m_model_fit(ctx, cfg, &Xv, &Yv, &model) == N4M_OK);
            n4m_array_t* arr = nullptr;
            N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, N4M_MODEL_WEIGHTS_W, &arr) == N4M_OK);
            expect_analytic(where, "weights_w", array_values(arr),
                            components == 1 ? std::vector<double>{1.0, 0.0}
                                            : std::vector<double>{1.0, 0.0, 0.0, 1.0});
            n4m_array_free(arr);
            N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, N4M_MODEL_COEFFICIENTS, &arr) ==
                             N4M_OK);
            std::vector<double> want = swapped ? std::vector<double>{d, 1.0, 0.0, 0.0}
                                               : std::vector<double>{1.0, d, 0.0, 0.0};
            if (components == 2) {
                want = swapped ? std::vector<double>{d, 1.0, 1.0, d}
                               : std::vector<double>{1.0, d, d, 1.0};
            }
            expect_analytic(where, "coefficients", array_values(arr), want);
            n4m_array_free(arr);
            n4m_model_destroy(model);
            n4m_config_destroy(cfg);
            n4m_context_destroy(ctx);
        }
    }
}

// (10) Close leading singular values with many targets, so that the reference
// dominant pair (Householder-QL on a nontrivial Gram matrix) is exercised:
// c3 = (1, -1, -1, 1) is orthogonal to a3 and b3 (||c3||^2 = 4), X = [a3, b3, c3],
// Y = [a3 + d b3, d a3 + b3, s_1 c3, ..., s_62 c3] with s_j = (64 + j) 2^-10.
// X'Y = [[20, 20 d, 0], [20 d, 20, 0], [0, 0, 4 s']] has the singular values
// 20 (1 +- d) and 4 ||s|| (~2.9): the dominant left singular vector is
// (1, 1, 0) / sqrt 2. One component: t = (a3 + b3) / sqrt 2, t't = 20 and
// t'Y_j = 0 for j >= 3, so the coefficients are h = (1 + d) / 2 in the
// leading 2 x 2 block and 0 elsewhere, the predictions h (a3 + b3) in the
// first two columns and 0 in the others (Y is centred).
void test_pls_close_singular_values_many_targets() {
    constexpr double kVecC3[4] = {1.0, -1.0, -1.0, 1.0};
    constexpr std::size_t q = 64;
    const std::vector<double> ab = combine3(1.0, 1.0);
    for (const int e : {12, 30}) {
        const double d = std::ldexp(1.0, -e);
        const double h = (1.0 + d) / 2.0;
        std::vector<double> x(12), y(4 * q), coefficients(3 * q, 0.0), predictions(4 * q, 0.0);
        for (std::size_t i = 0; i < 4; ++i) {
            x[i * 3] = kVecA3[i];
            x[i * 3 + 1] = kVecB3[i];
            x[i * 3 + 2] = kVecC3[i];
            y[i * q] = kVecA3[i] + d * kVecB3[i];
            y[i * q + 1] = d * kVecA3[i] + kVecB3[i];
            for (std::size_t j = 2; j < q; ++j) {
                y[i * q + j] = std::ldexp(static_cast<double>(64 + j - 1), -10) * kVecC3[i];
            }
            predictions[i * q] = predictions[i * q + 1] = h * ab[i];
        }
        coefficients[0] = coefficients[1] = coefficients[q] = coefficients[q + 1] = h;
        for (const AnalyticSolver& solver : kAnalyticSolvers) {
            if (solver.algorithm == N4M_ALGO_PCR) continue;  // X'X = diag(20, 20, 4): undetermined
            for (const double tol : {0.0, 1e-12}) {
                const std::string where = std::string(solver.tag) + (tol > 0.0 ? " tol 1e-12" : "") +
                                          " 64 targets, d = 2^-" + std::to_string(e);
                n4m_context_t* ctx = nullptr;
                n4m_config_t* cfg = nullptr;
                N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
                N4M_TEST_REQUIRE(n4m_config_create(&cfg) == N4M_OK);
                N4M_TEST_REQUIRE(n4m_config_set_n_components(cfg, 1) == N4M_OK);
                N4M_TEST_REQUIRE(n4m_config_set_algorithm(cfg, solver.algorithm) == N4M_OK);
                N4M_TEST_REQUIRE(n4m_config_set_solver(cfg, solver.solver) == N4M_OK);
                N4M_TEST_REQUIRE(n4m_config_set_scale_x(cfg, 0) == N4M_OK);
                N4M_TEST_REQUIRE(n4m_config_set_scale_y(cfg, 0) == N4M_OK);
                if (tol > 0.0) N4M_TEST_REQUIRE(n4m_config_set_tol(cfg, tol) == N4M_OK);
                n4m_matrix_view_t Xv{}, Yv{};
                N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&Xv, x.data(), 4, 3, N4M_DTYPE_F64) ==
                                 N4M_OK);
                N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(
                                     &Yv, y.data(), 4, static_cast<std::int64_t>(q),
                                     N4M_DTYPE_F64) == N4M_OK);
                n4m_model_t* model = nullptr;
                const n4m_status_t st = n4m_model_fit(ctx, cfg, &Xv, &Yv, &model);
                if (st != N4M_OK)
                    throw std::runtime_error(where + ": fit refused with status " +
                                             std::to_string(st));
                n4m_array_t* arr = nullptr;
                N4M_TEST_REQUIRE(n4m_model_get_array(ctx, model, N4M_MODEL_COEFFICIENTS, &arr) ==
                                 N4M_OK);
                expect_analytic(where, "coefficients", array_values(arr), coefficients);
                n4m_array_free(arr);
                std::vector<double> predicted(4 * q, 0.0);
                n4m_matrix_view_t Pv{};
                N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(
                                     &Pv, predicted.data(), 4, static_cast<std::int64_t>(q),
                                     N4M_DTYPE_F64) == N4M_OK);
                N4M_TEST_REQUIRE(n4m_model_predict(ctx, model, &Xv, &Pv) == N4M_OK);
                expect_analytic(where, "predictions", predicted, predictions);
                n4m_model_destroy(model);
                n4m_config_destroy(cfg);
                n4m_context_destroy(ctx);
            }
        }
    }
}

// ---- models.pls.opls: the OPLS kernel behind the generic estimator role ----
//
// The role adds no numerics: it fits N4M_ALGO_OPLS + N4M_SOLVER_NIPALS +
// N4M_DEFLATION_ORTHOGONAL through n4m_model_fit, with the other config
// defaults (the configuration of the R `opls_nipals` gateway). Only
// test_opls_role_oracle compares against an independent reference (the NumPy
// OPLS1 recurrence fixtures, row `pls4all-numpy-opls`); the other tests check
// the role wiring against the same kernel called directly.

constexpr const char* kOplsRole = "models.pls.opls";
constexpr const char* kPlsRole = "models.pls.pls_regression";

struct RoleFlags {
    std::int32_t n_components;
    bool center_x;
    bool scale_x;
    bool center_y;
    bool scale_y;
};

n4m_params_t* role_params(n4m_context_t* ctx, const char* method_id, const RoleFlags& f) {
    std::int32_t index = -1;
    N4M_TEST_REQUIRE(n4m_method_find(method_id, &index) == N4M_OK);
    n4m_params_t* params = nullptr;
    N4M_TEST_REQUIRE(n4m_params_create(ctx, index, &params) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_params_set_int(params, "n_components", f.n_components) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_params_set_bool(params, "center_x", f.center_x ? 1 : 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_params_set_bool(params, "scale_x", f.scale_x ? 1 : 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_params_set_bool(params, "center_y", f.center_y ? 1 : 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_params_set_bool(params, "scale_y", f.scale_y ? 1 : 0) == N4M_OK);
    return params;
}

n4m_fit_inputs_v1_t xy_inputs(const n4m_matrix_view_t& X, const n4m_matrix_view_t& Y) {
    n4m_fit_inputs_v1_t inputs{};
    inputs.struct_size = sizeof(inputs);
    inputs.X = &X;
    inputs.Y = &Y;
    return inputs;
}

n4m_estimator_t* fit_role(n4m_context_t* ctx, const char* method_id, const RoleFlags& f,
                          const n4m_matrix_view_t& X, const n4m_matrix_view_t& Y) {
    n4m_params_t* params = role_params(ctx, method_id, f);
    n4m_estimator_t* est = nullptr;
    N4M_TEST_REQUIRE(n4m_estimator_create(ctx, method_id, params, &est) == N4M_OK);
    n4m_params_destroy(params);
    const n4m_fit_inputs_v1_t inputs = xy_inputs(X, Y);
    N4M_TEST_REQUIRE(n4m_estimator_fit(ctx, est, &inputs) == N4M_OK);
    return est;
}

n4m_model_t* fit_direct(n4m_context_t* ctx, n4m_algorithm_t algorithm, n4m_solver_t solver,
                        n4m_deflation_t deflation, const RoleFlags& f,
                        const n4m_matrix_view_t& X, const n4m_matrix_view_t& Y) {
    n4m_config_t* cfg = nullptr;
    N4M_TEST_REQUIRE(n4m_config_create(&cfg) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_algorithm(cfg, algorithm) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_solver(cfg, solver) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_deflation(cfg, deflation) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_n_components(cfg, f.n_components) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_center_x(cfg, f.center_x ? 1 : 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_scale_x(cfg, f.scale_x ? 1 : 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_center_y(cfg, f.center_y ? 1 : 0) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_config_set_scale_y(cfg, f.scale_y ? 1 : 0) == N4M_OK);
    n4m_model_t* model = nullptr;
    N4M_TEST_REQUIRE(n4m_model_fit(ctx, cfg, &X, &Y, &model) == N4M_OK);
    n4m_config_destroy(cfg);
    return model;
}

n4m_model_t* fit_direct_opls(n4m_context_t* ctx, const RoleFlags& f,
                             const n4m_matrix_view_t& X, const n4m_matrix_view_t& Y) {
    return fit_direct(ctx, N4M_ALGO_OPLS, N4M_SOLVER_NIPALS, N4M_DEFLATION_ORTHOGONAL, f, X, Y);
}

std::vector<double> role_output(n4m_context_t* ctx, const n4m_estimator_t* est,
                                const n4m_matrix_view_t& X, bool transform) {
    std::int64_t cols = 0;
    N4M_TEST_REQUIRE((transform ? n4m_estimator_transform_cols(est, &cols)
                                : n4m_estimator_n_outputs(est, &cols)) == N4M_OK);
    std::vector<double> out(static_cast<std::size_t>(X.rows * cols), 0.0);
    n4m_matrix_view_t view{};
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&view, out.data(), X.rows, cols,
                                                   N4M_DTYPE_F64) == N4M_OK);
    N4M_TEST_REQUIRE((transform ? n4m_estimator_transform(ctx, est, &X, &view)
                                : n4m_estimator_predict(ctx, est, &X, &view)) == N4M_OK);
    return out;
}

std::vector<double> model_output(n4m_context_t* ctx, const n4m_model_t* model,
                                 const n4m_matrix_view_t& X, bool transform) {
    std::int32_t cols = 0;
    N4M_TEST_REQUIRE((transform ? n4m_model_get_n_components(model, &cols)
                                : n4m_model_get_n_targets(model, &cols)) == N4M_OK);
    std::vector<double> out(static_cast<std::size_t>(X.rows * cols), 0.0);
    n4m_matrix_view_t view{};
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&view, out.data(), X.rows, cols,
                                                   N4M_DTYPE_F64) == N4M_OK);
    N4M_TEST_REQUIRE((transform ? n4m_model_transform(ctx, model, &X, &view)
                                : n4m_model_predict(ctx, model, &X, &view)) == N4M_OK);
    return out;
}

std::vector<unsigned char> export_role(n4m_context_t* ctx, const n4m_estimator_t* est) {
    std::size_t size = 0;
    N4M_TEST_REQUIRE(n4m_estimator_export_size(ctx, est, 0, &size) == N4M_OK);
    std::vector<unsigned char> bytes(size);
    std::size_t written = 0;
    N4M_TEST_REQUIRE(n4m_estimator_export_to_buffer(ctx, est, 0, bytes.data(), size,
                                                    &written) == N4M_OK);
    bytes.resize(written);
    return bytes;
}

std::vector<unsigned char> export_model(const n4m_model_t* model) {
    std::size_t size = 0;
    N4M_TEST_REQUIRE(n4m_model_export_size(model, &size) == N4M_OK);
    std::vector<unsigned char> bytes(size);
    std::size_t written = 0;
    N4M_TEST_REQUIRE(n4m_model_export_to_buffer(model, bytes.data(), size, &written) == N4M_OK);
    bytes.resize(written);
    return bytes;
}

// An N4MM-state estimator envelope ends with its only block:
// u32 tag "N4MM" | u64 length | N4MM bytes | u64 FNV-1a-64 checksum.
constexpr std::size_t kN4meBlockHeader = 4 + 8;
constexpr std::size_t kN4meChecksum = 8;
constexpr unsigned char kN4mmTag[4] = {0x4E, 0x34, 0x4D, 0x4D};  // "N4MM"

std::uint64_t fnv1a64(const unsigned char* data, std::size_t size) {
    std::uint64_t h = 0xcbf29ce484222325ULL;
    for (std::size_t i = 0; i < size; ++i) {
        h ^= data[i];
        h *= 0x100000001b3ULL;
    }
    return h;
}

bool n4me_ends_with_block(const std::vector<unsigned char>& n4me,
                          const std::vector<unsigned char>& n4mm) {
    const std::size_t tail = kN4meBlockHeader + n4mm.size() + kN4meChecksum;
    if (n4me.size() < tail) return false;
    const unsigned char* block = n4me.data() + n4me.size() - tail;
    std::uint64_t length = 0;
    for (int i = 0; i < 8; ++i) {
        length |= static_cast<std::uint64_t>(block[4 + i]) << (8 * i);
    }
    return std::memcmp(block, kN4mmTag, 4) == 0 && length == n4mm.size() &&
           std::memcmp(block + kN4meBlockHeader, n4mm.data(), n4mm.size()) == 0;
}

// The envelope `n4me` (whose last block is `current`) with that block replaced
// by `replacement`, and its checksum recomputed.
std::vector<unsigned char> replace_n4mm_block(const std::vector<unsigned char>& n4me,
                                              const std::vector<unsigned char>& current,
                                              const std::vector<unsigned char>& replacement) {
    N4M_TEST_REQUIRE(n4me_ends_with_block(n4me, current));
    const std::size_t prefix = n4me.size() - kN4meBlockHeader - current.size() - kN4meChecksum;
    std::vector<unsigned char> out(n4me.begin(), n4me.begin() + static_cast<std::ptrdiff_t>(prefix));
    out.insert(out.end(), kN4mmTag, kN4mmTag + 4);
    const std::uint64_t length = replacement.size();
    for (int i = 0; i < 8; ++i) out.push_back(static_cast<unsigned char>(length >> (8 * i)));
    out.insert(out.end(), replacement.begin(), replacement.end());
    const std::uint64_t h = fnv1a64(out.data(), out.size());
    for (int i = 0; i < 8; ++i) out.push_back(static_cast<unsigned char>(h >> (8 * i)));
    return out;
}

double max_abs_difference(const std::vector<double>& a, const std::vector<double>& b) {
    N4M_TEST_REQUIRE(a.size() == b.size());
    double worst = 0.0;
    for (std::size_t i = 0; i < a.size(); ++i) worst = std::max(worst, std::fabs(a[i] - b[i]));
    return worst;
}

// (a) Independent oracle, default flags. Predictions and the transform
// (predictive score, then the orthogonal scores) must match the fixture's
// predict_train and scores_T at abs/rel 1e-9 with the generated per-column sign
// policy (sign_invariant MatrixRef). This is the gate for declaring the
// transformer role: a failure must not be met by loosening the tolerance or
// relabelling the output, and the transformer role must not ship.
void test_opls_role_oracle() {
    n4m_context_t* ctx = nullptr;
    N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
    for (const auto& fx : ::n4m::test::fixtures::kOplsFixtures) {
        const n4m_matrix_view_t X = make_view(fx.X);
        const n4m_matrix_view_t Y = make_view(fx.Y);
        n4m_estimator_t* est =
            fit_role(ctx, kOplsRole, {fx.n_components, true, true, true, true}, X, Y);
        const std::vector<double> pred = role_output(ctx, est, X, false);
        N4M_TEST_REQUIRE(pred.size() == fx.predict_train.size);
        check_close(fx.id, pred.data(), fx.predict_train);
        std::int64_t width = 0;
        N4M_TEST_REQUIRE(n4m_estimator_transform_cols(est, &width) == N4M_OK);
        N4M_TEST_REQUIRE(width == fx.n_components && width == fx.scores_t.cols);
        const std::vector<double> scores = role_output(ctx, est, X, true);
        N4M_TEST_REQUIRE(scores.size() == fx.scores_t.size);
        check_close((std::string(fx.id) + " transform").c_str(), scores.data(), fx.scores_t);
        n4m_estimator_destroy(est);
    }
    n4m_context_destroy(ctx);
}

// (b) Role wiring at non-default flags (n_components 3, unscaled X and Y)
// against the same kernel called directly. This is wiring parity, not an
// independent check of the mathematics.
void test_opls_role_wiring() {
    n4m_context_t* ctx = nullptr;
    N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
    const auto& fx = ::n4m::test::fixtures::kOplsFixtures[1];  // small PLS1
    const n4m_matrix_view_t X = make_view(fx.X);
    const n4m_matrix_view_t Y = make_view(fx.Y);
    const RoleFlags flags{3, true, false, true, false};
    n4m_estimator_t* est = fit_role(ctx, kOplsRole, flags, X, Y);
    n4m_model_t* direct = fit_direct_opls(ctx, flags, X, Y);

    const std::vector<double> pred = role_output(ctx, est, X, false);
    const std::vector<double> scores = role_output(ctx, est, X, true);
    N4M_TEST_REQUIRE(pred == model_output(ctx, direct, X, false));
    N4M_TEST_REQUIRE(scores == model_output(ctx, direct, X, true));

    // The N4ME carries exactly the direct model's N4MM (format 1) as its state.
    const std::vector<unsigned char> n4me = export_role(ctx, est);
    const std::vector<unsigned char> n4mm = export_model(direct);
    N4M_TEST_REQUIRE(n4me_ends_with_block(n4me, n4mm));
    n4m_serialized_model_info_v1_t info{};
    N4M_TEST_REQUIRE(n4m_serialization_inspect_model_v1(n4mm.data(), n4mm.size(), &info) ==
                     N4M_OK);
    N4M_TEST_REQUIRE(info.format_version == 1U);
    N4M_TEST_REQUIRE(info.algorithm == N4M_ALGO_OPLS);
    N4M_TEST_REQUIRE(info.solver == N4M_SOLVER_NIPALS);
    N4M_TEST_REQUIRE(info.deflation == N4M_DEFLATION_ORTHOGONAL);
    N4M_TEST_REQUIRE(info.n_components == 3);

    // Import restores the effective parameters and reproduces the outputs and
    // the bytes exactly.
    n4m_estimator_t* restored = nullptr;
    N4M_TEST_REQUIRE(n4m_estimator_import_from_buffer(ctx, n4me.data(), n4me.size(), &restored) ==
                     N4M_OK);
    n4m_params_t* params = nullptr;
    N4M_TEST_REQUIRE(n4m_estimator_get_params(ctx, restored, &params) == N4M_OK);
    const char* names[] = {"n_components", "center_x", "scale_x", "center_y", "scale_y"};
    const std::int64_t expected[] = {3, 1, 0, 1, 0};
    for (std::size_t i = 0; i < 5; ++i) {
        std::int64_t value = -1, count = 0;
        N4M_TEST_REQUIRE(n4m_params_get_int(params, names[i], &value, 1, &count) == N4M_OK);
        N4M_TEST_REQUIRE(count == 1 && value == expected[i]);
    }
    n4m_params_destroy(params);
    N4M_TEST_REQUIRE(role_output(ctx, restored, X, false) == pred);
    N4M_TEST_REQUIRE(role_output(ctx, restored, X, true) == scores);
    N4M_TEST_REQUIRE(export_role(ctx, restored) == n4me);

    n4m_estimator_destroy(restored);
    n4m_model_destroy(direct);
    n4m_estimator_destroy(est);
    n4m_context_destroy(ctx);
}

// (c) Ordinary PLS is unchanged and stays a different model. On one target,
// OPLS and PLS with the same total component count give the same predictions
// in exact arithmetic, so the prediction difference is checked on the fixed
// two-target fixture (one shared OPLS predictive direction against PLS2).
void test_opls_role_pls_control() {
    n4m_context_t* ctx = nullptr;
    N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
    const auto& fx = ::n4m::test::fixtures::kOplsFixtures[2];  // small PLS2, A = 3
    N4M_TEST_REQUIRE(fx.n_components == 3 && fx.Y.cols == 2);
    const n4m_matrix_view_t X = make_view(fx.X);
    const n4m_matrix_view_t Y = make_view(fx.Y);
    const RoleFlags flags{3, true, true, true, true};

    n4m_estimator_t* pls = fit_role(ctx, kPlsRole, flags, X, Y);
    n4m_model_t* direct_pls = fit_direct(ctx, N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_NIPALS,
                                         N4M_DEFLATION_REGRESSION, flags, X, Y);
    const std::vector<double> pls_pred = role_output(ctx, pls, X, false);
    N4M_TEST_REQUIRE(pls_pred == model_output(ctx, direct_pls, X, false));
    n4m_serialized_model_info_v1_t info{};
    const std::vector<unsigned char> pls_n4mm = export_model(direct_pls);
    N4M_TEST_REQUIRE(n4me_ends_with_block(export_role(ctx, pls), pls_n4mm));
    N4M_TEST_REQUIRE(n4m_serialization_inspect_model_v1(pls_n4mm.data(), pls_n4mm.size(),
                                                        &info) == N4M_OK);
    N4M_TEST_REQUIRE(info.algorithm == N4M_ALGO_PLS_REGRESSION);

    n4m_estimator_t* opls = fit_role(ctx, kOplsRole, flags, X, Y);
    N4M_TEST_REQUIRE(max_abs_difference(role_output(ctx, opls, X, false), pls_pred) > 1e-6);

    n4m_estimator_destroy(opls);
    n4m_model_destroy(direct_pls);
    n4m_estimator_destroy(pls);
    n4m_context_destroy(ctx);
}

// (d) Boundaries: OPLS has no solver parameter, and an N4ME labelled OPLS must
// carry an OPLS model.
void test_opls_role_refusals() {
    n4m_context_t* ctx = nullptr;
    N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
    std::int32_t index = -1;
    N4M_TEST_REQUIRE(n4m_method_find(kOplsRole, &index) == N4M_OK);
    n4m_params_t* params = nullptr;
    N4M_TEST_REQUIRE(n4m_params_create(ctx, index, &params) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_params_set_enum(params, "solver", "nipals") == N4M_ERR_INVALID_ARGUMENT);
    N4M_TEST_REQUIRE(n4m_params_set_int(params, "solver", 0) == N4M_ERR_INVALID_ARGUMENT);
    n4m_params_destroy(params);

    const auto& fx = ::n4m::test::fixtures::kOplsFixtures[1];
    const n4m_matrix_view_t X = make_view(fx.X);
    const n4m_matrix_view_t Y = make_view(fx.Y);
    const RoleFlags flags{3, true, false, true, false};
    n4m_estimator_t* est = fit_role(ctx, kOplsRole, flags, X, Y);
    const std::vector<unsigned char> n4me = export_role(ctx, est);
    n4m_model_t* direct_opls = fit_direct_opls(ctx, flags, X, Y);
    n4m_model_t* direct_pls = fit_direct(ctx, N4M_ALGO_PLS_REGRESSION, N4M_SOLVER_NIPALS,
                                         N4M_DEFLATION_REGRESSION, flags, X, Y);
    const std::vector<unsigned char> opls_n4mm = export_model(direct_opls);

    // Rebuilding the envelope around its own block still imports, so the
    // refusal below comes from the state, not from the rebuilt envelope.
    const std::vector<unsigned char> same = replace_n4mm_block(n4me, opls_n4mm, opls_n4mm);
    N4M_TEST_REQUIRE(same == n4me);
    n4m_estimator_t* restored = nullptr;
    N4M_TEST_REQUIRE(n4m_estimator_import_from_buffer(ctx, same.data(), same.size(), &restored) ==
                     N4M_OK);
    n4m_estimator_destroy(restored);

    // Same component count, flags, widths and capabilities: only the
    // algorithm of the state differs.
    const std::vector<unsigned char> foreign =
        replace_n4mm_block(n4me, opls_n4mm, export_model(direct_pls));
    restored = nullptr;
    N4M_TEST_REQUIRE(n4m_estimator_import_from_buffer(ctx, foreign.data(), foreign.size(),
                                                      &restored) == N4M_ERR_CORRUPT_BUFFER);
    N4M_TEST_REQUIRE(restored == nullptr);
    N4M_TEST_REQUIRE(std::strstr(n4m_context_last_error(ctx), "'algorithm'") != nullptr);

    n4m_model_destroy(direct_pls);
    n4m_model_destroy(direct_opls);
    n4m_estimator_destroy(est);
    n4m_context_destroy(ctx);
}

// RolePipeline: SNV then the OPLS regressor equals the steps run by hand, and
// the exported step states rebuild an identical pipeline.
void test_opls_role_pipeline() {
    n4m_context_t* ctx = nullptr;
    N4M_TEST_REQUIRE(n4m_context_create(&ctx) == N4M_OK);
    const auto& fx = ::n4m::test::fixtures::kOplsFixtures[1];
    const n4m_matrix_view_t X = make_view(fx.X);
    const n4m_matrix_view_t Y = make_view(fx.Y);
    const RoleFlags flags{3, true, false, true, false};
    const char* ids[] = {"preprocessing.scatter.snv", kOplsRole};
    n4m_params_t* opls_params = role_params(ctx, kOplsRole, flags);
    const n4m_params_t* step_params[] = {nullptr, opls_params};
    n4m_role_pipeline_t* pipeline = nullptr;
    N4M_TEST_REQUIRE(n4m_role_pipeline_create(ctx, 2, ids, step_params, &pipeline) == N4M_OK);
    const n4m_fit_inputs_v1_t inputs = xy_inputs(X, Y);
    N4M_TEST_REQUIRE(n4m_role_pipeline_fit(ctx, pipeline, &inputs) == N4M_OK);
    std::vector<double> got(static_cast<std::size_t>(X.rows * Y.cols), 0.0);
    n4m_matrix_view_t G{};
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&G, got.data(), X.rows, Y.cols,
                                                   N4M_DTYPE_F64) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_role_pipeline_predict(ctx, pipeline, &X, &G) == N4M_OK);

    n4m_estimator_t* snv = nullptr;
    N4M_TEST_REQUIRE(n4m_estimator_create(ctx, ids[0], nullptr, &snv) == N4M_OK);
    n4m_fit_inputs_v1_t snv_inputs{};
    snv_inputs.struct_size = sizeof(snv_inputs);
    snv_inputs.X = &X;
    N4M_TEST_REQUIRE(n4m_estimator_fit(ctx, snv, &snv_inputs) == N4M_OK);
    std::vector<double> x1 = role_output(ctx, snv, X, true);
    n4m_matrix_view_t X1{};
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&X1, x1.data(), X.rows, X.cols,
                                                   N4M_DTYPE_F64) == N4M_OK);
    n4m_estimator_t* opls = fit_role(ctx, kOplsRole, flags, X1, Y);
    N4M_TEST_REQUIRE(got == role_output(ctx, opls, X1, false));

    std::int32_t n_states = 0;
    N4M_TEST_REQUIRE(n4m_role_pipeline_n_states(pipeline, &n_states) == N4M_OK);
    N4M_TEST_REQUIRE(n_states == 2);
    std::vector<std::vector<unsigned char>> states(static_cast<std::size_t>(n_states));
    std::vector<const void*> state_ptrs;
    std::vector<std::size_t> state_sizes;
    for (std::int32_t s = 0; s < n_states; ++s) {
        auto& bytes = states[static_cast<std::size_t>(s)];
        std::size_t size = 0;
        N4M_TEST_REQUIRE(n4m_role_pipeline_export_state_size(ctx, pipeline, s, 0, &size) ==
                         N4M_OK);
        bytes.resize(size);
        std::size_t written = 0;
        N4M_TEST_REQUIRE(n4m_role_pipeline_export_state_to_buffer(ctx, pipeline, s, 0,
                                                                  bytes.data(), size,
                                                                  &written) == N4M_OK);
        bytes.resize(written);
        state_ptrs.push_back(bytes.data());
        state_sizes.push_back(bytes.size());
    }
    N4M_TEST_REQUIRE(states[1] == export_role(ctx, opls));
    n4m_role_pipeline_t* replay = nullptr;
    N4M_TEST_REQUIRE(n4m_role_pipeline_create(ctx, 2, ids, step_params, &replay) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_role_pipeline_import_states(ctx, replay, n_states, state_ptrs.data(),
                                                     state_sizes.data()) == N4M_OK);
    std::vector<double> again(got.size(), 0.0);
    n4m_matrix_view_t A{};
    N4M_TEST_REQUIRE(n4m_matrix_view_init_rowmajor(&A, again.data(), X.rows, Y.cols,
                                                   N4M_DTYPE_F64) == N4M_OK);
    N4M_TEST_REQUIRE(n4m_role_pipeline_predict(ctx, replay, &X, &A) == N4M_OK);
    N4M_TEST_REQUIRE(again == got);

    n4m_role_pipeline_destroy(replay);
    n4m_estimator_destroy(opls);
    n4m_estimator_destroy(snv);
    n4m_role_pipeline_destroy(pipeline);
    n4m_params_destroy(opls_params);
    n4m_context_destroy(ctx);
}

